    RANDOM = 'random'
    FLEE = 'flee'
    EATEN = 'eaten'

class Ghost:
    def __init__(self, name, initial_state):
        self.name = name
        self.state = initial_state
        self.edible = False
        self.edible_start_time = None

    def set_state(self, state):
        self.state = state

    def get_state(self):
        return self.state

    def is_edible(self):
        return self.edible

    def make_edible(self):
        self.edible = True
        self.edible_start_time = time.time()
        self.state = GhostState.FLEE

    def make_normal(self):
        self.edible = False
        self.edible_start_time = None

    def update(self):
        if self.edible and self.edible_start_time:
            if time.time() - self.edible_start_time > 10:  # edible lasts 10 seconds
                self.make_normal()
                self.state = self.initial_state

