    for ghost_name in gm.ghosts:
        assert gm.get_ghost_state(ghost_name) == GhostState.FLEE
    gm.deactivate_power_pellet()
    assert gm.power_pellet_active == False


def test_update_reverts_state_after_power_pellet():
