    gm.deactivate_power_pellet()
    for ghost_name in gm.ghosts:
        assert gm.is_edible(ghost_name) == False

// UI component for Ghost Identity & State Visuals
// This component will fetch ghost states from the backend and display their identity and state visually

class GhostIdentityStateVisuals {
    constructor(containerId) {
        this.container = document.getElementById(containerId);
        this.ghostStates = [];
        this.pollInterval = 1000; // ms
        this.timer = null;
    }

    async fetchGhostStates() {
        try {
            const response = await fetch('/ghost-states');
            if (!response.ok) throw new Error('Failed to fetch ghost states');
            this.ghostStates = await response.json();
            this.render();
        } catch (error) {
            console.error('Error fetching ghost states:', error);
        }
    }

    render() {
        if (!this.container) return;
        this.container.innerHTML = '';

        this.ghostStates.forEach(ghost => {
            const ghostDiv = document.createElement('div');
            ghostDiv.className = 'ghost-identity-state p-2 m-2 rounded border border-gray-600 flex items-center space-x-4';

            const colorBox = document.createElement('div');
            colorBox.style.backgroundColor = ghost.color || 'gray';
            colorBox.className = 'w-8 h-8 rounded-full border border-black';

            const infoDiv = document.createElement('div');
            infoDiv.className = 'text-white';
            infoDiv.innerHTML = `
                <div><strong>Name:</strong> ${ghost.name}</div>
                <div><strong>State:</strong> ${ghost.state}</div>
            `;

            ghostDiv.appendChild(colorBox);
            ghostDiv.appendChild(infoDiv);

            this.container.appendChild(ghostDiv);
        });
    }

    start() {
        this.fetchGhostStates();
        this.timer = setInterval(() => this.fetchGhostStates(), this.pollInterval);
    }

    stop() {
        if (this.timer) {
            clearInterval(this.timer);
            this.timer = null;
        }
    }
}

export default GhostIdentityStateVisuals;

