        self.name = name
        self.state = GhostState.IDLE
        self.original_state = self.state

    def activate(self):
        self.state = GhostState.CHASE
        self.original_state = self.state

    def sleep(self):
        self.state = GhostState.FRIGHTENED

    def is_active(self) -> bool:
        return self.state == GhostState.CHASE

