// This module implements enhanced game state overlays for the game UI.
// It provides functions to activate, update, and dismiss overlays that
// display game state information such as score, lives, level, and power pellet status.

let currentOverlay = null;

export function activateOverlay(overlayId, content) {
  // Create overlay element if not exists
  let overlay = document.getElementById(overlayId);
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = overlayId;
    overlay.className = 'fixed top-4 left-4 bg-black bg-opacity-75 text-white p-4 rounded shadow-lg z-50';
    document.body.appendChild(overlay);
  }
  overlay.innerHTML = content;
  overlay.style.display = 'block';
  currentOverlay = overlay;
}

export function updateOverlay(content) {
  if (currentOverlay) {
    currentOverlay.innerHTML = content;
  }
}

export function dismissOverlay() {
  if (currentOverlay) {
    currentOverlay.style.display = 'none';
    currentOverlay = null;
  }
}

// Helper to format game state info into HTML
export function formatGameStateOverlay(gameState) {
  // gameState: { score, lives, level, powerPelletActive, timeLeft }
  return `
    <div class="space-y-2">
      <div><strong>Score:</strong> ${gameState.score}</div>
      <div><strong>Lives:</strong> ${gameState.lives}</div>
      <div><strong>Level:</strong> ${gameState.level}</div>
      <div><strong>Power Pellet:</strong> ${gameState.powerPelletActive ? 'Active' : 'Inactive'}</div>
      ${gameState.powerPelletActive ? `<div><strong>Time Left:</strong> ${gameState.timeLeft}s</div>` : ''}
    </div>
  `;
}

