// This file implements the Ghost Identity & State Visuals feature

// Ghost identities and their colors
const ghostColors = {
  Blinky: '#ff5555',
  Pinky: '#ff9ed8',
  Inky: '#5ad2ff',
  Clyde: '#ffb852'
};

// Ghost states
const GhostState = {
  CHASE: 'CHASE',
  SCATTER: 'SCATTER',
  FRIGHTENED: 'FRIGHTENED',
  EATEN: 'EATEN'
};

// Draw a ghost on canvas context ctx at pixel position (cx, cy)
// with a given state and identity
export function drawGhost(ctx, cx, cy, state, identity) {
  let fillColor;
  switch(state) {
    case GhostState.FRIGHTENED:
      fillColor = '#3b4cff';
      break;
    case GhostState.EATEN:
      fillColor = '#ffffff'; // white body for eyes only
      break;
    default:
      fillColor = ghostColors[identity] || '#ff5555';
  }

  const r = 15; // radius for ghost body
  ctx.fillStyle = fillColor;
  ctx.beginPath();
  ctx.arc(cx, cy, r, Math.PI, 0); // domed head
  ctx.lineTo(cx + r, cy + r);
  ctx.lineTo(cx - r, cy + r);
  ctx.closePath();
  ctx.fill();

  // Eyes
  if(state === GhostState.EATEN) {
    ctx.fillStyle = '#000000';
    const eyeRadius = r / 4;
    ctx.beginPath();
    ctx.arc(cx - r / 2.5, cy - r / 5, eyeRadius, 0, Math.PI * 2);
    ctx.arc(cx + r / 2.5, cy - r / 5, eyeRadius, 0, Math.PI * 2);
    ctx.fill();
  } else {
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(cx - r / 2.5, cy - r / 5, r / 4, 0, Math.PI * 2);
    ctx.arc(cx + r / 2.5, cy - r / 5, r / 4, 0, Math.PI * 2);
    ctx.fill();
  }
}

// Export GhostState for use in game logic
export { GhostState };

