// Frontend module to display ghost identity and state visuals

// This module fetches ghost states from the backend and updates the UI accordingly

async function fetchGhostStates() {
  try {
    const response = await fetch('/ghost-states');
    if (!response.ok) {
      throw new Error('Failed to fetch ghost states');
    }
    const ghostStates = await response.json();
    updateGhostVisuals(ghostStates);
  } catch (error) {
    console.error('Error fetching ghost states:', error);
  }
}

function updateGhostVisuals(ghostStates) {
  // For each ghost, update its identity and state visuals
  ghostStates.forEach(ghost => {
    const ghostElement = document.getElementById(`ghost-${ghost.id}`);
    if (!ghostElement) return;

    // Update identity display
    ghostElement.querySelector('.ghost-identity').textContent = ghost.identity;

    // Update state visuals (e.g. color, opacity) based on ghost.state
    ghostElement.className = `ghost ${ghost.state}`;
  });
}

// Periodically refresh ghost states
setInterval(fetchGhostStates, 1000);

// Initial fetch
fetchGhostStates();

