// src/frontend/ghost_identity_ui.js

// This module fetches ghost states from the backend and renders a UI panel
// showing each ghost's identity and current state visually.

const ghostColors = {
  blinky: 'text-red-600',
  pinky: 'text-pink-500',
  inky: 'text-cyan-500',
  clyde: 'text-orange-500',
  unknown: 'text-gray-500'
};

const ghostStateLabels = {
  normal: 'Normal',
  frightened: 'Frightened',
  eaten: 'Eaten',
  unknown: 'Unknown'
};

let ghostStates = [];

// Create the container element for the ghost identity UI
const container = document.createElement('div');
container.id = 'ghost-identity-ui';
container.className = 'fixed top-4 right-4 bg-white bg-opacity-80 rounded-lg p-4 shadow-lg max-w-xs font-sans';
container.innerHTML = '<h2 class="text-lg font-bold mb-2">Ghost Identity & State</h2>';
document.body.appendChild(container);

// Render the ghost states inside the container
function renderGhostStates() {
  if (!ghostStates.length) {
    container.innerHTML = '<h2 class="text-lg font-bold mb-2">Ghost Identity & State</h2><p class="text-gray-600">Loading...</p>';
    return;
  }

  const content = ghostStates.map(ghost => {
    const colorClass = ghostColors[ghost.identity] || ghostColors.unknown;
    const stateLabel = ghostStateLabels[ghost.state] || ghostStateLabels.unknown;
    return `
      <div class="flex items-center space-x-3 mb-2">
        <div class="w-6 h-6 rounded-full bg-gray-300 flex items-center justify-center">
          <span class="${colorClass} font-bold">${ghost.identity.charAt(0).toUpperCase()}</span>
        </div>
        <div>
          <div class="font-semibold capitalize">${ghost.identity}</div>
          <div class="text-sm text-gray-700">State: ${stateLabel}</div>
        </div>
      </div>
    `;
  }).join('');

  container.innerHTML = `<h2 class="text-lg font-bold mb-2">Ghost Identity & State</h2>${content}`;
}

// Fetch ghost states from backend API
export async function fetchGhostStates() {
  try {
    const response = await fetch('/ghost-states');
    if (!response.ok) {
      throw new Error('Failed to fetch ghost states');
    }
    ghostStates = await response.json();
    renderGhostStates();
  } catch (error) {
    container.innerHTML = `<h2 class="text-lg font-bold mb-2">Ghost Identity & State</h2><p class="text-red-600">Error loading ghost states</p>`;
    console.error('Error fetching ghost states:', error);
  }
}

// Initial render with loading state
renderGhostStates();

